const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const TOKEN = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const fail = (r) => { throw new Fail(`error: line ${i + 1}: ${r}`) }
    const int = (v, field, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    const decl = () => { if (events.length) fail('declarations must come before the first event') }
    if (d === 'bucket') {
      if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      decl()
      if (!TOKEN.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const capacity = int(f[2], 'capacity', 1)
      const refill = int(f[3], 'refill', 0)
      const per = int(f[4], 'per', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per, state: new Map() })
    } else if (d === 'window') {
      if (f.length !== 4) fail('expected window <name> <limit> <span>')
      decl()
      if (!TOKEN.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const limit = int(f[2], 'limit', 0)
      const span = int(f[3], 'span', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'window', limit: BigInt(limit), span, state: new Map() })
    } else if (d === 'route') {
      if (f.length < 3) fail('expected route <prefix> <policy>...')
      decl()
      if (!TOKEN.test(f[1])) fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
      const ps = f.slice(2).map((n) => {
        if (!policies.has(n)) fail(`unknown policy ${n}`)
        return policies.get(n)
      })
      routes.set(f[1], ps)
    } else if (d === 'event') {
      if (f.length !== 3) fail('expected event <tick> <key>')
      const tick = int(f[1], 'tick', 0)
      if (!TOKEN.test(f[2])) fail(`invalid key ${f[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: f[2] })
    } else fail(`unknown directive ${d}`)
  })
  return { routes, events }
}

function run({ routes, events }) {
  const out = []
  const stats = new Map()
  let ta = 0, td = 0
  const prefixes = [...routes.keys()]
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    const ps = best === null ? [] : routes.get(best)
    const sts = ps.map((p) => {
      let s = p.state.get(key)
      if (!s) {
        s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
        p.state.set(key, s)
      }
      if (p.kind === 'bucket') {
        const cap = p.capacity * p.per
        s.num += p.refill * (tick - s.last)
        if (s.num > cap) s.num = cap
        s.last = tick
      } else {
        const cut = tick - p.span
        s.ticks = s.ticks.filter((t) => t > cut)
      }
      return s
    })
    let denied = null
    for (let i = 0; i < ps.length && denied === null; i++) {
      const p = ps[i]
      const ok = p.kind === 'bucket' ? sts[i].num >= p.per : BigInt(sts[i].ticks.length) < p.limit
      if (!ok) denied = p.name
    }
    if (denied === null) {
      ps.forEach((p, i) => {
        if (p.kind === 'bucket') sts[i].num -= p.per
        else sts[i].ticks.push(tick)
      })
    }
    const st = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, st)
    if (denied === null) { st.a++; ta++ } else { st.d++; td++ }
    out.push(denied === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denied}`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') + `total allowed=${ta} denied=${td}\n`
}

import { readFileSync } from 'node:fs'
let result
try {
  result = run(parse(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
process.stdout.write(result)
EOF
