{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261127T225309Z/cell-1XQYXl/src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(node) {
  return [...node.m.keys()].sort(cmp)
}

function scalar(node) {
  if (node.t === 'integer') return node.v.toString()
  return JSON.stringify(node.v)
}

function ser(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node.t === 'table') {
    const ks = sortedKeys(node)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + ser(node.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((v) => pad + ser(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return scalar(node)
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

export function toKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : path + '.' + k
        const c = node.m.get(k)
        out.push(p + ' ' + c.t)
        walk(c, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = path + '[' + i + ']'
        out.push(p + ' ' + c.t)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261127T225309Z/cell-1XQYXl/src/parser.js","content":"export class ParseError extends Error {}

const BARE = /[A-Za-z0-9_-]/
const newTable = () => ({ t: 'table', m: new Map(), made: false })

function fail(msg) {
  throw new ParseError(msg)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  // at end of the directive: end of line or start of a comment
  atEnd() {
    return this.i >= this.s.length || this.s[this.i] === '#' || this.s[this.i] === ';'
  }
  peek() {
    return this.s[this.i]
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        break
      }
    }
    return names
  }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.s[this.i++]
      switch (e) {
        case '"': out += '"'; break
        case '\\': out += '\\'; break
        case 'n': out += '\n'; break
        case 't': out += '\t'; break
        case 'r': out += '\r'; break
        case '0': out += '\0'; break
        case 'u': {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
          break
        }
        default: {
          const ch = String.fromCodePoint(this.s.codePointAt(this.i - 1))
          fail('invalid escape \\' + ch)
        }
      }
    }
  }

  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }

  value(path) {
    this.ws()
    if (this.atEnd()) fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !/[ \t,\]};]/.test(this.s[this.i])) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true') return { t: 'boolean', v: true }
    if (tok === 'false') return { t: 'boolean', v: false }
    const run = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${run}$`).test(tok)) {
      return { t: 'integer', v: BigInt(tok.replace(/_/g, '').replace(/^\+/, '')) }
    }
    if (new RegExp(`^[+-]?${run}(?:\\.${run}(?:[eE][+-]?${run})?|[eE][+-]?${run})$`).test(tok)) {
      return { t: 'float', v: Number(tok.replace(/_/g, '')) }
    }
    fail('invalid value ' + tok)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        break
      }
      items.push(this.value(`${path}[${items.length}]`))
      this.ws()
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === ']') {
        this.i++
        break
      }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.peek() === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(path + '.' + names.join('.'))
      assign(tbl, path, names, v)
      this.ws()
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === '}') {
        this.i++
        break
      }
      fail('unterminated inline table')
    }
    return tbl
  }
}

const join = (base, names) => (base ? base + '.' : '') + names.join('.')

// Walk names through tables (and last elements of arrays of tables), creating tables.
function walk(tbl, base, names) {
  for (let k = 0; k < names.length; k++) {
    let c = tbl.m.get(names[k])
    if (c === undefined) {
      c = newTable()
      tbl.m.set(names[k], c)
    } else if (c.t === 'array' && c.aot) {
      c = c.items[c.items.length - 1]
    } else if (c.t !== 'table') {
      fail(`${join(base, names.slice(0, k + 1))} is not a table`)
    }
    tbl = c
  }
  return tbl
}

