const err = (code) => ({ t: 'e', v: code })
const num = (v) => ({ t: 'n', v })
const ZERO = num(0)

// ---- address helpers
function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, key: L + row }
}
function colName(c) {
  return c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
}
const keyOf = (col, row) => colName(col) + row

// ---- read sheet
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key -> {col,row,content}
const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
lines.forEach((raw, idx) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const tok = m[0]
  let rest = line.slice(tok.length).replace(/^[ \t]+/, '')
  const a = parseAddr(tok)
  if (!a) fail(`error: line ${idx + 1}: invalid cell address ${tok}`)
  if (cells.has(a.key)) fail(`error: line ${idx + 1}: cell ${tok} is declared twice`)
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content: rest })
})

// ---- formula parsing
function lex(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
