    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const out = []
  let conflict = false
  const emit = (kind, ls, extra) => {
    if (mode === 'regions') out.push(extra ?? `${kind} ${ls.length}`)
    else out.push(...ls)
  }
  let pos = 0, k = 0
  while (k < all.length) {
    if (all[k].bs > pos) {
      const s = base.slice(pos, all[k].bs)
      emit('stable', s)
    }
    const group = [all[k++]]
    const R0 = group[0].bs
    let R1 = group[0].be
    while (k < all.length && all[k].bs <= R1) {
      R1 = Math.max(R1, all[k].be)
      group.push(all[k++])
    }
    pos = R1
    if (group.length === 1) {
      const c = group[0]
      const ls = (c.who === 0 ? mine : theirs).slice(c.ss, c.se)
      emit(c.who === 0 ? 'mine' : 'theirs', ls)
      continue
    }
    const baseR = base.slice(R0, R1)
    const rep = (who, doc) => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseR
