        if (mode === 'merge') out.push('||||||| base', ...baseR)
        out.push('=======', ...th, '>>>>>>> theirs')
      }
    }
  }
  if (pos < base.length) emit('stable', base.slice(pos))
  if (mode === 'regions') {
    // drop empty stable regions
  }
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
