import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if (!((mode === 'waves' || mode === 'explain') && args.length === 1) && !(mode === 'pack' && args.length === 2)) {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}
if (mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cost = new Map()
const deps = new Map()
const depLines = []
lines.forEach((raw, i) => {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})
for (const name of cost.keys()) deps.set(name, new Set())
for (const names of depLines) {
  for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
  for (const d of names.slice(1)) deps.get(names[0]).add(d)
}
const names = [...cost.keys()].sort()
const sortedDeps = new Map(names.map((n) => [n, [...deps.get(n)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of sortedDeps.get(u)) {
      if (state.get(v) === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!state.has(v)) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const n of names) if (!state.has(n)) visit(n)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const visit = (u) => {
  if (finish.has(u)) return
  let s = 0n
  let d = 0
  for (const v of sortedDeps.get(u)) {
    visit(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
names.forEach(visit)
let total = 0n
for (const f of finish.values()) if (f > total) total = f

const out = []
if (mode === 'waves') {
  const maxD = names.reduce((m, n) => Math.max(m, depth.get(n)), -1)
  for (let k = 0; k <= maxD; k++) out.push(`wave ${k}: ${names.filter((n) => depth.get(n) === k).join(' ')}`)
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const n of names) out.push(`${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
  out.push(`total ${total}`)
} else {
  const rev = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of sortedDeps.get(n)) rev.get(d).push(n)
  const prio = new Map()
  const pv = (u) => {
    if (prio.has(u)) return prio.get(u)
    let best = 0n
    for (const v of rev.get(u)) { const p = pv(v); if (p > best) best = p }
    prio.set(u, best + cost.get(u))
    return prio.get(u)
  }
  names.forEach(pv)
  const fin = new Map()
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const pending = new Set(names)
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let pick = null
      for (const n of names) {
        if (!pending.has(n)) continue
        if (!sortedDeps.get(n).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick)) pick = n
      }
      if (pick === null) break
      pending.delete(pick)
      const f = t + cost.get(pick)
      fin.set(pick, f)
      freeAt[wi] = f
      ran[wi].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
