const isIdStart = (c) => c === '_' || isLetter(c)
const isIdChar = (c) => isIdStart(c) || isDigit(c)

export function scan(source) {
  const cs = Array.from(source)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  // Advance one code point, tracking the position.
  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, reason) => {
    throw new ScanError(l, c, reason)
  }

