    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    const tl = line
    const tc = col
    const push = (kind, body) => tokens.push({ line: tl, column: tc, kind, body })

