        if (cs[i] === '/' && cs[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
      if (depth > 0) fail(tl, tc, 'unterminated block comment')
      continue
    }

