function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) { flush(); i++; j++; bs = i; ss = j }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return res
}

export function merge(mine, base, theirs, mode) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const regions = []
  for (let k = 0; k < all.length;) {
    const r = { start: all[k].bs, end: all[k].be, ch: [all[k]] }
    k++
    while (k < all.length && all[k].bs <= r.end) {
      r.end = Math.max(r.end, all[k].be); r.ch.push(all[k]); k++
    }
    regions.push(r)
  }
  const out = []
  let conflict = false
  let pos = 0
  const emitStable = to => {
    if (to > pos) {
      if (mode === 'regions') out.push(`stable ${to - pos}`)
      else out.push(...base.slice(pos, to))
    }
  }
  const side = (r, who, lines) => {
    const c = r.ch.filter(x => x.who === who)
    if (!c.length) return base.slice(r.start, r.end)
    const minB = Math.min(...c.map(x => x.bs)), maxB = Math.max(...c.map(x => x.be))
    const minS = Math.min(...c.map(x => x.ss)), maxS = Math.max(...c.map(x => x.se))
    return lines.slice(minS - (minB - r.start), maxS + (r.end - maxB))
  }
  const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
  for (const r of regions) {
    emitStable(r.start)
    const b = base.slice(r.start, r.end)
    let label, lines
    if (r.ch.length === 1) {
      const c = r.ch[0]
      label = c.who === 0 ? 'mine' : 'theirs'
      lines = (c.who === 0 ? mine : theirs).slice(c.ss, c.se)
    } else {
      const m = side(r, 0, mine), t = side(r, 1, theirs)
      if (eq(m, t)) { label = 'both'; lines = m }
      else if (eq(m, b)) { label = 'theirs'; lines = t }
      else if (eq(t, b)) { label = 'mine'; lines = m }
      else {
        conflict = true
        if (mode === 'regions') out.push(`conflict mine=${m.length} base=${b.length} theirs=${t.length}`)
        else {
          out.push('<<<<<<< mine', ...m)
          if (mode === 'merge') out.push('||||||| base', ...b)
          out.push('=======', ...t, '>>>>>>> theirs')
        }
        pos = r.end
        continue
      }
    }
    if (mode === 'regions') out.push(`${label} ${lines.length}`)
    else out.push(...lines)
    pos = r.end
  }
  emitStable(base.length)
  return { out, conflict }
}
