  const addr = m[1]
  const p = parseAddr(addr)
  if (!p) fail(`error: line ${i + 1}: invalid cell address ${addr}`)
  const key = keyOf(p.col, p.row)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
