function refValue(name) {
  const p = parseAddr(name)
  if (!p) return err('#REF!')
  return cellValue(keyOf(p.col, p.row))
}

function toNum(v) {
  if (v.k === 'e') return v
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}

function rangeValues(a, b) {
  const p = parseAddr(a), q = parseAddr(b)
  if (!p || !q) return [err('#REF!')]
  const out = []
  for (let c = Math.min(p.col, q.col); c <= Math.max(p.col, q.col); c++)
    for (let r = Math.min(p.row, q.row); r <= Math.max(p.row, q.row); r++) out.push(cellValue(keyOf(c, r)))
