{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(v, field, least) {
  if (!INT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

function run(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let last = null

  const parse = (line) => {
    const f = line.split(/\s+/)
    const d = f[0]
    const exp = {
      bucket: 'bucket <name> <capacity> <refill> <per>',
      window: 'window <name> <limit> <span>',
      route: 'route <prefix> <policy>...',
      event: 'event <tick> <key>',
    }
    if (!(d in exp) || !Object.hasOwn(exp, d)) throw new Fail(`unknown directive ${d}`)
    const n = { bucket: 5, window: 4, event: 3 }[d]
    if (d === 'route' ? f.length < 3 : f.length !== n) throw new Fail(`expected ${exp[d]}`)
    if (d !== 'event' && started) throw new Fail('declarations must come before the first event')
    if (d === 'bucket' || d === 'window') {
      if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
      let p
      if (d === 'bucket') {
        const capacity = int(f[2], 'capacity', 1)
        const refill = int(f[3], 'refill', 0)
        const per = int(f[4], 'per', 1)
        p = { kind: 'bucket', name: f[1], capacity, refill, per }
      } else {
        const limit = int(f[2], 'limit', 0)
        const span = int(f[3], 'span', 1)
        p = { kind: 'window', name: f[1], limit, span }
      }
      if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], p)
    } else if (d === 'route') {
      if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
      for (const p of f.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
      routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
    } else {
      const tick = int(f[1], 'tick', 0)
      if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
      if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
      started = true
      last = tick
      event(tick, f[1], f[2])
    }
  }

  const event = (tick, tickText, key) => {
    let best = null
    for (const [prefix, list] of routes) if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const k = p.name + '\0' + key
        let s = states.get(k)
        if (!s) {
          s = p.kind === 'bucket' ? { num: p.capacity * p.per, at: tick } : { ticks: [] }
          states.set(k, s)
        }
        if (p.kind === 'bucket') {
          s.num += p.refill * (tick - s.at)
          s.at = tick
          if (s.num > p.capacity * p.per) s.num = p.capacity * p.per
        } else {
          s.ticks = s.ticks.filter((t) => t > tick - p.span)
        }
        return s
      })
      for (let i = 0; i < list.length && denied === null; i++) {
        const p = list[i]
        const ok = p.kind === 'bucket' ? sts[i].num >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) denied = p.name
      }
      if (denied === null) {
        list.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].num -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    const st = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, st)
    if (denied === null) st.a++
    else st.d++
    if (mode === 'replay') out.push(denied === null ? `${tickText} ${key} allow` : `${tickText} ${key} deny ${denied}`)
  }

  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try {
      parse(line)
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  if (mode === 'summary') {
    let a = 0
    let d = 0
    for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      const s = stats.get(k)
      a += s.a
      d += s.d
      out.push(`${k} allowed=${s.a} denied=${s.d}`)
    }
    out.push(`total allowed=${a} denied=${d}`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}

try {
  process.stdout.write(run(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
